function CountVowels(s: string): int
    requires s != null
    ensures Result >= 0
{
    var total := 0;
    var length := s.Length;
    var i := 0;

    while i < length
        invariant 0 <= i <= length
        invariant total >= 0
    {
        if IsVowel(s[i], i == length - 1) {
            total := total + 1;
        }
        i := i + 1;
    }
    total
}

